pub fn HashMapMixin(comptime Self: type, comptime K: type, comptime V: type, comptime Context: type) type {
        return struct {

pub fn clearRetainingCapacity(map_self: *Self) void {
            _ = @memset(map_self.slice(), Self.Entry);
