    }

pub fn slice(map_self: *Self) []Self.Entry {
            const capacity = cp_shl((if (comptime @typeInfo(@TypeOf(1)) == .@"enum") cp_cast_int(u64, @intFromEnum(1)) else cp_cast_int(u64, 1)), ((63 - map_self.shift) + 1));
            const overflow = cp_shl(((capacity / 10) + ((63 - (if (comptime @typeInfo(@TypeOf(map_self.shift)) == .@"enum") cp_cast_int(usize, @intFromEnum(map_self.shift)) else cp_cast_int(usize, map_self.shift))) + 1)), 1);
            {
