            }
    }

pub fn putAssumeCapacity(map_self: *Self, key: K, value: V) void {
            _ = map_self.putAssumeCapacityContext(key, value, undefined);
    }

pub fn putAssumeCapacityContext(map_self: *Self, key: K, value: V, ctx: Context) void {
            const result = map_self.getOrPutAssumeCapacityContext(key, ctx);
            if ((!result.found_existing)) {
                {
                    result.value_ptr.* = value;
                }
            }
    }

pub fn getOrPutAssumeCapacity(map_self: *Self, key: K) Self.GetOrPutResult {
            return map_self.getOrPutAssumeCapacityContext(key, undefined);
    }

pub fn getOrPutAssumeCapacityContext(map_self: *Self, key: K, ctx: Context) Self.GetOrPutResult {
            var it: Self.Entry = Self.Entry{ .hash = ctx.hash(key), .key = key, .value = undefined };
            _ = &it;
            var i = cp_shr(it.hash, map_self.shift);
            _ = &i;
            _ = assert((it.hash != Self.empty_hash));
            var inserted_at: ?usize = null;
            _ = &inserted_at;
            while (true) : (i = (i + 1)) {
                {
                    const entry = map_self.entries[@as(usize, @intCast(i))];
                    if ((entry.hash >= it.hash)) {
                        if (ctx.eql(entry.key, key)) {
                            return Self.GetOrPutResult{ .found_existing = true, .value_ptr = (&(if (@typeInfo(@TypeOf(map_self.entries[@as(usize, @intCast(i))])) == .@"enum") @intFromEnum(map_self.entries[@as(usize, @intCast(i))]) else map_self.entries[@as(usize, @intCast(i))].value)) };
                        }
                        map_self.entries[cp_cast_int(usize, i)] = it;
                        if (entry.isEmpty()) {
                            map_self.len = (map_self.len + 1);
                            return Self.GetOrPutResult{ .found_existing = false, .value_ptr = (&(if (@typeInfo(@TypeOf(map_self.entries[@as(usize, @intCast(((inserted_at) orelse (i))))])) == .@"enum") @intFromEnum(map_self.entries[@as(usize, @intCast(((inserted_at) orelse (i))))]) else map_self.entries[@as(usize, @intCast(((inserted_at) orelse (i))))].value)) };
                        }
                        if ((inserted_at == null)) {
                            inserted_at = i;
                        }
                        it = entry;
                    }
                }
            }
    }

pub fn get(map_self: *const Self, key: K) ?V {
            return map_self.getContext(key, undefined);
    }

pub fn getContext(map_self: *const Self, key: K, ctx: Context) ?V {
            const hash = ctx.hash(key);
            _ = assert((hash != Self.empty_hash));
            {
                for (cp_iter_slice(map_self.entries[cp_shr(hash, map_self.shift)..])) |entry| {
                    _ = &entry;
                    if ((entry.hash >= hash)) {
                        if ((!ctx.eql(entry.key, key))) {
                            return null;
                        }
                        return (if (@typeInfo(@TypeOf(entry)) == .@"enum") @intFromEnum(entry) else entry.value);
                    }
                }
            }
    }

pub fn has(map_self: *const Self, key: K) bool {
            return map_self.hasContext(key, undefined);
    }

pub fn hasWithHash(map_self: *const Self, key_hash: u64) bool {
            _ = assert((key_hash != Self.empty_hash));
            {
                for (cp_iter_slice(map_self.entries[cp_shr(key_hash, map_self.shift)..])) |entry| {
                    _ = &entry;
                    if ((entry.hash >= key_hash)) {
                        return (entry.hash == key_hash);
                    }
                }
            }
            return false;
    }

pub fn hasContext(map_self: *const Self, key: K, ctx: Context) bool {
            const hash = ctx.hash(key);
            _ = assert((hash != Self.empty_hash));
            {
                for (cp_iter_slice(map_self.entries[cp_shr(hash, map_self.shift)..])) |entry| {
                    _ = &entry;
                    if ((entry.hash >= hash)) {
                        if ((!ctx.eql(entry.key, key))) {
                            return false;
                        }
                        return true;
                    }
                }
            }
            _ = unreachable;
    }

pub fn delete(map_self: *Self, key: K) ?V {
            return map_self.deleteContext(key, undefined);
    }

pub fn deleteContext(map_self: *Self, key: K, ctx: Context) ?V {
            const hash = ctx.hash(key);
            _ = assert((hash != Self.empty_hash));
            var i = cp_shr(hash, map_self.shift);
            _ = &i;
            {
                while (true) : (i = (i + 1)) {
                    const entry = map_self.entries[@as(usize, @intCast(i))];
                    if ((entry.hash >= hash)) {
                        if ((!ctx.eql(entry.key, key))) {
                            return null;
                        }
                        break;
                    }
                }
                const value = (if (@typeInfo(@TypeOf(map_self.entries[@as(usize, @intCast(i))])) == .@"enum") @intFromEnum(map_self.entries[@as(usize, @intCast(i))]) else map_self.entries[@as(usize, @intCast(i))].value);
                while (true) : (i = (i + 1)) {
                    const j = cp_shr(map_self.entries[@as(usize, @intCast((i + 1)))].hash, map_self.shift);
                    if (((i < j) or map_self.entries[@as(usize, @intCast((i + 1)))].isEmpty())) {
