                    }
                    map_self.entries[cp_cast_int(usize, i)] = map_self.entries[@as(usize, @intCast((i + 1)))];
                }
                map_self.entries[cp_cast_int(usize, i)] = Self.Entry;
                map_self.len = (map_self.len - 1);
                return value;
            }
    }
};
